from collections import deque
R,C=24,25
outside=set(); q=deque()
for r in range(R):
 for c in range(C):
  if (r in (0,R-1) or c in (0,C-1)) and rows[r][c]==9:
   outside.add((r,c));q.append((r,c))
while q:
 r,c=q.popleft()
 for dr in (-1,0,1):
  for dc in (-1,0,1):
   nr,nc=r+dr,c+dc
   if 0<=nr<R and 0<=nc<C and rows[nr][nc]==9 and (nr,nc) not in outside:
    outside.add((nr,nc));q.append((nr,nc))
holes=[(r,c) for r in range(R) for c in range(C) if rows[r][c]==9 and (r,c) not in outside]
holes, len(holes)
